(function(){const s=document.getElementById("site-navigation");if(!s)return;const t=s.getElementsByTagName("button")[0];if(!t)return;const e=s.getElementsByClassName("js-menu")[0];if(!e){t.classList.add("hidden");return}t.addEventListener("click",function(n){n.stopPropagation(),e.classList.toggle("hidden");const i=!e.classList.contains("hidden");t.setAttribute("aria-expanded",i?"true":"false")}),document.addEventListener("keydown",function(n){e.classList.contains("hidden")||n.key==="Escape"&&(n.preventDefault(),e.classList.add("hidden"),t.setAttribute("aria-expanded","false"),t.focus())}),document.addEventListener("click",function(n){if(e.classList.contains("hidden"))return;const i=n.target;i instanceof Node&&!s.contains(i)&&(e.classList.add("hidden"),t.setAttribute("aria-expanded","false"))})})();
